MOTIF_NAME = 'centralized_knight'
MOTIF_DESCRIPTION = 'Side to move has a knight on one of the four central squares (d4, d5, e4, e5)'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn

    central_squares = [chess.D4, chess.D5, chess.E4, chess.E5]

    for sq in board.pieces(chess.KNIGHT, stm):
        if sq in central_squares:
            return True
    return False
